/** Dedicated Finance operations from the official Seller OpenAPI. */
export class DigikalaFinanceApi {
  constructor(private readonly transport: DigikalaAxiosTransport) {}

  /**
   * Seller financial overview: per-state totals, next settlement date, and sales/sales-returns breakdown. The **metadata** carries `statuses`: the `status` filter options as `{value, label}`, the same shape `/transactions` returns.
   * @scope invoice
   * @operation GET /open-api/v1/finance/overview/v2
   */
  getFinanceOverviewV2(
    input: GetFinanceOverviewV2Input,
  ): Promise<GetFinanceOverviewV2Output> {
    return this.transport.request({
      method: 'GET',
      path: 'finance/overview/v2',
      input,
      inputSchema: GetFinanceOverviewV2InputSchema,
      outputSchema: GetFinanceOverviewV2OutputSchema,
      serialize: (input) => ({ params: input.query }),
    });
  }

  /**
   * Seller transaction list with filters, sort, and pagination. `transaction_time` is the only sortable column and accepts `asc` and `desc`, defaulting to `desc`. `pager.total_rows` and `pager.total_pages` no longer count the result: finance-billing reports only whether a next page exists, so both are a floor derived from that — one row past the current page while more pages remain, and the page's own last row on the final page. Page forward until a page comes back shorter than `pager.item_per_page`; do not render either number as the size of the result.
   * @scope invoice
   * @operation GET /open-api/v1/finance/transactions
   */
  getFinanceTransactions(
    input: GetFinanceTransactionsInput = {},
  ): Promise<GetFinanceTransactionsOutput> {
    return this.transport.request({
      method: 'GET',
      path: 'finance/transactions',
      input,
      inputSchema: GetFinanceTransactionsInputSchema,
      outputSchema: GetFinanceTransactionsOutputSchema,
      serialize: (input) => ({ params: input.query }),
    });
  }

  /**
   * Seller transaction row-level list with filters, sort, and pagination. `transaction_time` is the only sortable column and accepts both `asc` and `desc`, defaulting to `desc`. `pager.total_rows` and `pager.total_pages` no longer count the result: finance-billing reports only whether a next page exists, so both are a floor derived from that — one row past the current page while more pages remain, and the page's own last row on the final page. Page forward until a page comes back shorter than `pager.item_per_page`; do not render either number as the size of the result. Without `start_date`, finance-billing applies its own default window of the last 90 days ending today, so an unfiltered request is the last 90 days rather than the seller's whole history. Pass `start_date` to widen it.
   * @scope invoice
   * @operation GET /open-api/v1/finance/transactions/rows
   */
  getFinanceTransactionsRows(
    input: GetFinanceTransactionsRowsInput = {},
  ): Promise<GetFinanceTransactionsRowsOutput> {
    return this.transport.request({
      method: 'GET',
      path: 'finance/transactions/rows',
      input,
      inputSchema: GetFinanceTransactionsRowsInputSchema,
      outputSchema: GetFinanceTransactionsRowsOutputSchema,
      serialize: (input) => ({ params: input.query }),
    });
  }

  /**
   * Seller per-state totals for the current Persian month, plus the next and last settlements, and the seller's payout cycle. Takes no period parameters: `total` and `paid` always cover the current month, and the pending / accepted / released states are the seller's live balance.
   * @scope invoice
   * @operation GET /open-api/v1/finance/transactions/summary
   */
  getFinanceTransactionsSummary(
    input: GetFinanceTransactionsSummaryInput = {},
  ): Promise<GetFinanceTransactionsSummaryOutput> {
    return this.transport.request({
      method: 'GET',
      path: 'finance/transactions/summary',
      input,
      inputSchema: GetFinanceTransactionsSummaryInputSchema,
      outputSchema: GetFinanceTransactionsSummaryOutputSchema,
      serialize: () => ({}),
    });
  }

  /**
   * Single transaction detail mirroring finance-billing structure.
   * @scope invoice
   * @operation GET /open-api/v1/finance/transactions/{transaction_id}
   */
  getFinanceTransactionsByTransactionId(
    input: GetFinanceTransactionsByTransactionIdInput,
  ): Promise<GetFinanceTransactionsByTransactionIdOutput> {
    return this.transport.request({
      method: 'GET',
      path: `finance/transactions/${encodeURIComponent(String(input.path['transaction_id']))}`,
      input,
      inputSchema: GetFinanceTransactionsByTransactionIdInputSchema,
      outputSchema: GetFinanceTransactionsByTransactionIdOutputSchema,
      serialize: () => ({}),
    });
  }

  /**
   * Seller payout order history, filtered, sorted and paged in memory: finance-billing's /payout-orders/history accepts only the seller and whether to include pending payouts, so none of it can be pushed downstream.
   * @scope invoice
   * @operation GET /open-api/v1/finance/payouts
   */
  getFinancePayouts(
    input: GetFinancePayoutsInput = {},
  ): Promise<GetFinancePayoutsOutput> {
    return this.transport.request({
      method: 'GET',
      path: 'finance/payouts',
      input,
      inputSchema: GetFinancePayoutsInputSchema,
      outputSchema: GetFinancePayoutsOutputSchema,
      serialize: (input) => ({ params: input.query }),
    });
  }

  /**
   * Single payout order detail mirroring finance-billing structure.
   * @scope invoice
   * @operation GET /open-api/v1/finance/payouts/{payout_id}
   */
  getFinancePayoutsByPayoutId(
    input: GetFinancePayoutsByPayoutIdInput,
  ): Promise<GetFinancePayoutsByPayoutIdOutput> {
    return this.transport.request({
      method: 'GET',
      path: `finance/payouts/${encodeURIComponent(String(input.path['payout_id']))}`,
      input,
      inputSchema: GetFinancePayoutsByPayoutIdInputSchema,
      outputSchema: GetFinancePayoutsByPayoutIdOutputSchema,
      serialize: () => ({}),
    });
  }

  /**
   * Monthly seller invoices issued by the finance team.
   * @scope invoice
   * @operation GET /open-api/v1/finance/seller-invoices
   */
  getFinanceSellerInvoices(
    input: GetFinanceSellerInvoicesInput = {},
  ): Promise<GetFinanceSellerInvoicesOutput> {
    return this.transport.request({
      method: 'GET',
      path: 'finance/seller-invoices',
      input,
      inputSchema: GetFinanceSellerInvoicesInputSchema,
      outputSchema: GetFinanceSellerInvoicesOutputSchema,
      serialize: (input) => ({ params: input.query }),
    });
  }

  /**
   * Requests an excel export of the seller's finance transactions. The file is built in the background and then emailed to the seller and listed under /files/exports.
   * @scope invoice
   * @operation POST /open-api/v1/finance/transactions/export/excel
   */
  postFinanceTransactionsExportExcel(
    input: PostFinanceTransactionsExportExcelInput = {},
  ): Promise<PostFinanceTransactionsExportExcelOutput> {
    return this.transport.request({
      method: 'POST',
      path: 'finance/transactions/export/excel',
      input,
      inputSchema: PostFinanceTransactionsExportExcelInputSchema,
      outputSchema: PostFinanceTransactionsExportExcelOutputSchema,
      serialize: (input) => ({ params: input.query, data: input.body }),
    });
  }
}
